#include <iostream>
#include <iomanip>

int main() {
    // 1. Character constant as integer
    char ch = 'z';
    std::cout << "Character '" << ch << "' numeric value: " << static_cast<int>(ch) << "\n";

    // 2. Mutable array vs const char* pointer to string literal
    char mutableWord[] = "blue";
    const char* literalPtr = "blue";

    mutableWord[0] = 'B'; // OK: array elements are mutable
    std::cout << "Modified array: " << mutableWord << "\n";
    std::cout << "String literal: " << literalPtr << "\n";

    // 3. Preventing buffer overflow via bounded field width
    // Buffer size is 10, so max characters read must be 9 + 1 for '\0'
    char safeBuffer[10];
    if (std::cin >> std::setw(10) >> safeBuffer) {
        std::cout << "Safely extracted: " << safeBuffer << "\n";
    }

    return 0;
}

#include <iostream>
#include <cctype>

void inspectChar(char ch) {
    unsigned char uc = static_cast<unsigned char>(ch);
    std::cout << "Inspecting '" << ch << "':\n";
    std::cout << "  isdigit : " << (std::isdigit(uc) ? "true" : "false") << "\n";
    std::cout << "  isalpha : " << (std::isalpha(uc) ? "true" : "false") << "\n";
    std::cout << "  isalnum : " << (std::isalnum(uc) ? "true" : "false") << "\n";
    std::cout << "  isxdigit: " << (std::isxdigit(uc) ? "true" : "false") << "\n";
}

int main() {
    inspectChar('8');
    inspectChar('A');
    inspectChar('f');
    inspectChar('#');
    return 0;
}
